import { Injectable } from '@angular/core';

export interface PaginationData {
  total_items: number;
  total_pages: number;
  current_page: number;
  page_size: number;
  has_next: boolean;
  has_prev: boolean;
  next_page: number | null;
  prev_page: number | null;
}

@Injectable({
  providedIn: 'root',
})
export class PaginationService {
  private paginationData: PaginationData = {
    total_items: 0,
    total_pages: 0,
    current_page: 1,
    page_size: 10,
    has_next: false,
    has_prev: false,
    next_page: null,
    prev_page: null,
  };

  constructor() {}

  setPaginationData(data: PaginationData) {
    this.paginationData = data;
  }

  getPaginationData(): PaginationData {
    return this.paginationData;
  }

  getNextPage(): number | null {
    return this.paginationData.has_next ? this.paginationData.next_page : null;
  }

  getPrevPage(): number | null {
    return this.paginationData.has_prev ? this.paginationData.prev_page : null;
  }
}
